using System.Collections;
using System.Reflection;
using TownOfHost;
static class Program{
 static readonly Type Service=typeof(DiscordMatchmakingRelayService);
 const BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Static;
 static object Get(string name)=>Service.GetField(name,Flags).GetValue(null);
 static void Set(string name,object value)=>Service.GetField(name,Flags).SetValue(null,value);
 static bool Active=>(bool)Get("_activeRecruitment");
 static async Task Drain()=>await ((Task)Get("_sendTail")).WaitAsync(TimeSpan.FromSeconds(5));
 static void Check(bool ok){if(!ok)throw new Exception("Lifecycle assertion failed (values omitted).");}
 static async Task Reset(){await Drain();((IList)Get("Recruitments")).Clear();Set("_current",null);Set("_activeRecruitment",false);Set("_forceUpdateRequested",false);Set("_failureNotice",false);Set("_maintenanceNotice",false);Set("_refreshButtons",false);Set("_nextRecruitmentStartAtMs",0L);TownOfHost.Main.MatchmakingRelayUrl="https://relay.example/";LifecycleHarness.FailAllRequests=false;LifecycleHarness.Maintenance=false;Set("_nextUpdateAtMs",0L);Set("_sendTail",Task.CompletedTask);AmongUsClient.Instance=new();GameStates.IsInGame=false;GameStates.IsLobby=true;LifecycleHarness.Calls.Clear();LifecycleHarness.Sessions.Clear();LifecycleHarness.Tokens.Clear();Logger.Lines.Clear();LifecycleHarness.FailNextUpdate=false;LifecycleHarness.HoldUpdate=null;}
 static async Task Start(){DiscordMatchmakingRelayService.ToggleRecruitment(new GameStartManager());await Drain();Check(Active);}
 static void Due(){Set("_nextUpdateAtMs",0L);}
 static int count;
 static async Task Test(string name,Func<Task> run){await Reset();await run();Check(!Logger.Lines.Any(line=>LifecycleHarness.Tokens.Any(token=>line.Contains(token))));count++;Console.WriteLine("PASS "+name);}
 public static async Task Main(){
  await Test("recruitment UI start/end/restart creates separate sessions",async()=>{await Start();var first=Get("_current");DiscordMatchmakingRelayService.ToggleRecruitment(new());Set("_nextRecruitmentStartAtMs",0L);DiscordMatchmakingRelayService.ToggleRecruitment(new());await Drain();Check(Active&&!ReferenceEquals(first,Get("_current")));Check(LifecycleHarness.Sessions.Count==2&&LifecycleHarness.Sessions.Values.Count(s=>s.Ended)==1);});
  await Test("ExitGame hook ends owned recruitment",async()=>{await Start();DeleteDiscordMatchmakingOnExitPatch.Prefix();await Drain();Check(!Active&&LifecycleHarness.Sessions.Values.All(s=>s.Ended));});
  await Test("disconnect hook ends owned recruitment",async()=>{await Start();DeleteDiscordMatchmakingOnDisconnectPatch.Prefix();await Drain();Check(!Active&&LifecycleHarness.Sessions.Values.All(s=>s.Ended));});
  await Test("host loss stops recruitment",async()=>{await Start();AmongUsClient.Instance.AmHost=false;Due();DiscordMatchmakingRelayService.Tick();await Drain();Check(!Active&&LifecycleHarness.Sessions.Values.All(s=>s.Ended));});
  await Test("room change closes prior recruitment",async()=>{await Start();AmongUsClient.Instance.GameId=2;Due();DiscordMatchmakingRelayService.Tick();await Drain();Check(!Active&&LifecycleHarness.Sessions.Values.All(s=>s.Ended));});
  await Test("game start hook captures InGame state",async()=>{await Start();AmongUsClient.Instance.IsGameStarted=true;UpdateDiscordMatchmakingOnStartGamePatch.Postfix();DiscordMatchmakingRelayService.Tick();await Drain();Check(Active&&LifecycleHarness.Calls.Last().Body.Contains("InGame"));});
  await Test("unchanged lobby uses a heartbeat without another start",async()=>{await Start();var current=Get("_current");current.GetType().GetField("LastSentAtMs").SetValue(current,Environment.TickCount64-120001);Due();DiscordMatchmakingRelayService.Tick();await Drain();Check(LifecycleHarness.Calls.Count(c=>c.Path.EndsWith("/start"))==1&&LifecycleHarness.Calls.Count(c=>c.Path.EndsWith("/update"))==2);});
  await Test("network failure backs off then safely retries same update",async()=>{await Start();LifecycleHarness.FailNextUpdate=true;AmongUsClient.Instance.allClients.Add(6);Due();DiscordMatchmakingRelayService.Tick();await Drain();var before=LifecycleHarness.Calls.Count;Due();DiscordMatchmakingRelayService.Tick();await Drain();Check(LifecycleHarness.Calls.Count==before);var current=Get("_current");current.GetType().GetField("RetryAtMs").SetValue(current,0L);Due();DiscordMatchmakingRelayService.Tick();await Drain();Check(Active&&LifecycleHarness.Calls.Count==before+1);});
  await Test("late old response cannot erase the new room recruitment",async()=>{var release=new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);LifecycleHarness.HoldUpdate=release;LifecycleHarness.UpdateEntered=new(TaskCreationOptions.RunContinuationsAsynchronously);DiscordMatchmakingRelayService.ToggleRecruitment(new());await LifecycleHarness.UpdateEntered.Task.WaitAsync(TimeSpan.FromSeconds(5));DeleteDiscordMatchmakingOnExitPatch.Prefix();AmongUsClient.Instance.GameId=2;Set("_nextRecruitmentStartAtMs",0L);DiscordMatchmakingRelayService.ToggleRecruitment(new());var current=Get("_current");release.SetResult(true);await Drain();Check(Active&&ReferenceEquals(current,Get("_current")));Check(LifecycleHarness.Sessions.Values.Count(s=>s.Ended)==1&&LifecycleHarness.Sessions.Values.Count(s=>s.Room=="UVWXYZ"&&!s.Ended)==1);});
  await Test("non-host cannot register or mutate recruitment",async()=>{AmongUsClient.Instance.AmHost=false;DiscordMatchmakingRelayService.ToggleRecruitment(new());DiscordMatchmakingRelayService.RequestImmediateUpdate("test");DiscordMatchmakingRelayService.Tick();await Drain();Check(!Active&&LifecycleHarness.Calls.Count==0);});
  await Test("rapid public-private-public does not repost during cooldown",async()=>{await Start();DiscordMatchmakingRelayService.ToggleRecruitment(new());DiscordMatchmakingRelayService.ToggleRecruitment(new());await Drain();Check(!Active&&LifecycleHarness.Sessions.Count==1&&LifecycleHarness.Sessions.Values.All(s=>s.Ended));});
  await Test("maintenance response ends local waiting and shows fixed unavailable notice",async()=>{LifecycleHarness.Maintenance=true;DiscordMatchmakingRelayService.ToggleRecruitment(new());await Drain();Check(!Active);DiscordMatchmakingRelayService.Tick();await Drain();Check(Logger.Lines.Any(l=>l.Contains("現在マッチメイキング"))&&LifecycleHarness.Calls.Count==1);});
  await Test("missing endpoint never sends HTTP and preserves maintenance notice",async()=>{TownOfHost.Main.MatchmakingRelayUrl="none";DiscordMatchmakingRelayService.ToggleRecruitment(new());await Drain();Check(!Active&&LifecycleHarness.Calls.Count==0&&Logger.Lines.Any(l=>l.Contains("現在マッチメイキング")));});
  await Test("five start network failures stop automatic retry",async()=>{LifecycleHarness.FailAllRequests=true;DiscordMatchmakingRelayService.ToggleRecruitment(new());await Drain();for(int n=0;n<4;n++){var current=Get("_current");Check(current!=null);current.GetType().GetField("RetryAtMs").SetValue(current,0L);Due();DiscordMatchmakingRelayService.Tick();await Drain();}Check(!Active&&LifecycleHarness.Calls.Count==5);for(int n=0;n<10;n++){Due();DiscordMatchmakingRelayService.Tick();}await Drain();Check(LifecycleHarness.Calls.Count==5);});
  await Test("lost host cannot issue a new room recruitment",async()=>{await Start();AmongUsClient.Instance.AmHost=false;DeleteDiscordMatchmakingOnDisconnectPatch.Prefix();await Drain();Set("_nextRecruitmentStartAtMs",0L);DiscordMatchmakingRelayService.ToggleRecruitment(new());await Drain();Check(!Active&&LifecycleHarness.Sessions.Count==1);});
  await Test("configuration disabled still closes the already-owned session",async()=>{await Start();TownOfHost.Main.MatchmakingRelayUrl="none";DiscordMatchmakingRelayService.Tick();await Drain();Check(!Active&&LifecycleHarness.Sessions.Values.All(s=>s.Ended));});
  await Test("UI reports preparing until Relay acknowledges then shows public",async()=>{var release=new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);LifecycleHarness.HoldUpdate=release;LifecycleHarness.UpdateEntered=new(TaskCreationOptions.RunContinuationsAsynchronously);var screen=new GameStartManager();DiscordMatchmakingRelayService.ToggleRecruitment(screen);await LifecycleHarness.UpdateEntered.Task.WaitAsync(TimeSpan.FromSeconds(5));Check(screen.HostPrivateButton.buttonText.text=="募集準備中");release.SetResult(true);await Drain();DiscordMatchmakingRelayService.Tick();Check(screen.HostPrivateButton.buttonText.text=="公開中");});
  Console.WriteLine($"Shell lifecycle (actual patch, HTTP/Unity substitutes): {count} passed, 0 failed.");
 }
}
